# Validate inputs
for arr in [logp_with_result, logp_call_only, logp_no_call]:
    if not isinstance(arr, np.ndarray) or arr.ndim != 2:
        raise ValueError("Each input must be a 2D numpy array")
    if arr.size == 0:
        raise ValueError("Input array cannot be empty")
    if not np.isfinite(arr).all():
        raise ValueError("All values must be finite")
    if (arr > 0).any():
        raise ValueError("All values must be nonpositive")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Input arrays must have the same shape")
if isinstance(tau_filter, bool):
    raise ValueError("tau_filter must not be a boolean")
if not np.isfinite(tau_filter):
    raise ValueError("tau_filter must be finite")
if tau_filter < 0:
    raise ValueError("tau_filter must be nonnegative")

# Compute margins
sum_with = logp_with_result.sum(axis=1)
sum_call_only = logp_call_only.sum(axis=1)
sum_no_call = logp_no_call.sum(axis=1)
baseline = np.maximum(sum_no_call, sum_call_only)
margin = sum_with - baseline
keep = margin >= tau_filter
return keep, margin
